package com.ryanjei.orushio.pve.http;
import static org.junit.jupiter.api.Assertions.*;import com.ryanjei.orushio.pve.application.*;import com.ryanjei.orushio.pve.domain.*;import com.ryanjei.orushio.pve.logging.AuditSink;import com.ryanjei.orushio.pve.map.*;import com.ryanjei.orushio.pve.persistence.ActiveSessionRepository;import com.ryanjei.orushio.pve.security.AuthService;import java.net.*;import java.net.http.*;import java.nio.file.Path;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.*;
class HttpMethodContractTest{AdminHttpServer server;HttpClient client;String base,cookie,csrf;@BeforeEach void start()throws Exception{ServerAdministrationService admin=new ServerAdministrationService(){public List<OnlinePlayerView> onlinePlayers(){return List.of();}public boolean whitelistEnabled(){return false;}public boolean setWhitelistEnabled(boolean value){return value;}public List<WhitelistEntryView> whitelistedPlayers(){return List.of();}public WhitelistEntryView addWhitelistedPlayer(String name){throw new UnsupportedOperationException();}public void removeWhitelistedPlayer(String name){}};server=new AdminHttpServer(InetAddress.getByName("127.0.0.1"),0,new DefaultGameApplicationService(new MemorySession()),admin,new EmptyMaps(),new AuthService(),Map::of,new AuditSink(){public void record(String a,String b,String c,String d){}public boolean healthy(){return true;}},false);server.start();client=HttpClient.newHttpClient();base="http://127.0.0.1:"+server.port();String token=server.issueBootstrapToken();var auth=client.send(HttpRequest.newBuilder(URI.create(base+"/auth/bootstrap")).header("X-Bootstrap-Token",token).POST(HttpRequest.BodyPublishers.noBody()).build(),HttpResponse.BodyHandlers.ofString());cookie=auth.headers().firstValue("Set-Cookie").orElseThrow().split(";",2)[0];csrf=field(auth.body(),"csrfToken");}@AfterEach void stop(){server.close();}@Test void phase1And2GetApiWrongMethodIs405()throws Exception{assertEquals(405,post("/api/v1/status").statusCode());assertEquals(405,post("/api/v1/players").statusCode());}@Test void phase3MapApiWrongMethodIs405()throws Exception{assertEquals(405,post("/api/v1/maps").statusCode());}@Test void unknownEndpointIs404()throws Exception{assertEquals(404,post("/api/v1/not-found").statusCode());}private HttpResponse<String> post(String path)throws Exception{return client.send(HttpRequest.newBuilder(URI.create(base+path)).header("Cookie",cookie).header("Origin",base).header("X-CSRF-Token",csrf).POST(HttpRequest.BodyPublishers.ofString("{}")).build(),HttpResponse.BodyHandlers.ofString());}private static String field(String json,String key){String marker="\""+key+"\":\"";int start=json.indexOf(marker)+marker.length();return json.substring(start,json.indexOf('"',start));}private static final class MemorySession implements ActiveSessionRepository{GameSession value;public Optional<GameSession> load(){return Optional.ofNullable(value);}public void save(GameSession session){value=session;}}private static final class EmptyMaps implements MapAdministrationService{public List<MapProfile> list(){return List.of();}public Optional<String> fixedNextMapId(){return Optional.empty();}public MapProfile importZip(Path p,String id,String name){throw new UnsupportedOperationException();}public MapProfile setEnabled(String id,boolean enabled){throw new UnsupportedOperationException();}public void fixNext(String id){}public void delete(String id){}public SetupView startSetup(String id,UUID admin,String state){return SetupView.inactive();}public SetupView setup(){return SetupView.inactive();}public void selectField(UUID admin,String field,boolean area){}public void recordClick(UUID admin,BlockPoint point,boolean corner){}public MapProfile saveSetup(String session){throw new UnsupportedOperationException();}public void discardSetup(String session){}}}
